INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.103.0',
  '2026-09-24',
  'Пульт ТВ: заставку и титры находит сам — по звуку',
  E'Размечать серии руками больше не нужно. В админке у сериала («✂» → сезон) появилась кнопка «🎧 Найти заставку и титры по звуку»: агент слушает начало и конец каждой серии, находит кусок, который во всех сериях звучит одинаково, — это и есть заставка и титры — и расставляет отметки сам. Сезон разбирается минут двадцать, заниматься в это время можно чем угодно.\n\nГалочка «Пропускать с самого начала» ставит начало заставки в ноль: тогда «Пропустить» убирает и повтор прошлых серий, который по звуку не найти.\n\nРядом с «Во весь экран» появилась кнопка «⏭ Пропуск»: выключает подсказки у этого сериала, не стирая отметки, — если заставку вдруг захочется посмотреть.\n\nStar Trek: Strange New Worlds размечен так целиком: три сезона, тридцать серий.',
  E'media-agent: fingerprint.go — отпечатки звука. ffmpeg отдаёт моно 8 кГц, окно 2048 отсчётов (256 мс) с шагом 512 (64 мс), 21 полоса спектра логарифмом (100–3500 Гц), бит на пару соседних полос по правилу chromaprint (стала ли полоса громче соседней по сравнению с предыдущим кадром) — 20 бит на кадр, устойчиво к громкости и кодеку.\n\n⚠️ Окно вчетверо длиннее шага не для красоты: с окном 256 отсчётов совпадение находилось ТОЛЬКО в самом начале файла, где сетка кадров у двух серий сходится случайно. Заставка начинается не в круглое число кадров, и при коротком окне те же ноты попадают в разные его половины.\n\nСдвиг ищется полным перебором: для каждого доля кадров с расхождением ≤6 бит (случайный сдвиг даёт 0,07, настоящий — 0,14 и выше); 14 тысяч кадров на 14 тысяч — четверть секунды. Голосование по точному совпадению отпечатков оказалось негодным: внутри заставки ровно те же 20 бит выпадают лишь у каждого двадцатого кадра. Дальше при лучших сдвигах ищется самый длинный участок совпадения: ядро по доле 0,5 в окне ±0,5 с, края тянутся по 0,15.\n\nКонец отметки дотягивается до ближайшей паузы (snapForward): последние 10–15 секунд заставки LostFilm озвучивает названием серии, и совпадение там обрывается на полминуты раньше конца. Берётся НАЧАЛО паузы — конец её это уже тихий первый кадр сцены.\n\nscan.go — работа целиком: серия сравнивается с четырьмя другими с разных концов сезона, из всех найденных кусков заставкой считается тот, что кончается позже всех (перед ней стоит заставка студии-переводчика, тоже общая), титрами — начинающийся позже всех и не дальше 600 с от конца. Титры-выбросы подтягиваются к медиане сезона (у одной серии совпала музыка сцены за 237 с до конца). Отметки пишутся на уровень серии: пролог у каждой своей длины. Задача одна за раз, ход работы и остановка — /api/admin/marks/scan.\n\nmarks.go: поле skip_off (кнопка «⏭ Пропуск» у плеера, пишется на сериал). Галочки auto_skip и skip_off теперь складываются по уровням, а не перекрываются: иначе запись серии, добавленная поиском, сбрасывала выключатель, поставленный на сериал.\n\nГрабли: startScan присваивал структуру задачи целиком под её же захваченным замком — копия обнуляла мьютекс, и агент падал на Unlock («sync: unlock of unlocked mutex»). Поймано в браузере на первом же запуске.\n\nПроверено: три сезона Strange New Worlds на настоящих файлах — 28 заставок из 30 (в двух сериях своей заставки нет вовсе, что подтверждено поиском известной темы в их звуке), титры у всех 68–69 с до конца; выборочно сверено с кадрами (S01E04: музыка кончается на 746, титры идут до 749). Синтетические тесты на отпечатки, паузу и медиану — в fingerprint_test.go.'
);
-- +goose StatementEnd

